/**
 * ChatBridge is the bound service of the WebView chat surface. Bound methods
 * run on their own goroutines, so every call marshals onto the window UI
 * lane before touching Shell state.
 */
export const chat = {
  /**
   * AnswerInteraction claims the interaction (CAS, first answer wins) and
   * delivers the choice as the option's arrow-navigation key sequence —
   * arrows, never digits, which would type into the TUI (the reference
   * transport's rule). The interaction is consumed even if the delivery
   * fails: the agent stays blocked and may re-ask.
   */
  answerInteraction(interactionID: string, option: string): Promise<ChatBridgeState> {
    return call("chat.AnswerInteraction", interactionID, option);
  },
  /**
   * AnswerInteractionMulti answers a multi-select question: from the first row
   * the rows to tick are walked with down/space, then enter submits.
   */
  answerInteractionMulti(interactionID: string, options: string[]): Promise<ChatBridgeState> {
    return call("chat.AnswerInteractionMulti", interactionID, options);
  },
  /**
   * AnswerInteractionText answers a free-text option: the option is selected
   * by the same arrow navigation, then the typed answer is pasted and
   * submitted through the canonical agent.prompt once the TUI's text field
   * has focus. An empty answer is refused — selecting without text is what
   * produced "no answer provided".
   */
  answerInteractionText(interactionID: string, option: string, text: string): Promise<ChatBridgeState> {
    return call("chat.AnswerInteractionText", interactionID, option, text);
  },
  /**
   * CancelQueued cancels every cancellable follow-up of the bound
   * conversation (an entry mid-delivery stays) and returns the projection.
   */
  cancelQueued(): Promise<ChatBridgeState> {
    return call("chat.CancelQueued");
  },
  /**
   * CancelQueuedItem withdraws one follow-up by request id before its
   * delivery commit and returns the projection; a commit race surfaces in
   * the projection's Outcome instead of failing the call.
   */
  cancelQueuedItem(requestID: string): Promise<ChatBridgeState> {
    return call("chat.CancelQueuedItem", requestID);
  },
  /**
   * Catalog lists the Skills, commands and models the composer can offer. It
   * reads the provider's own files (and pi/omp's read-only model listing, cached
   * ten minutes) and executes no command.
   */
  catalog(): Promise<ChatCatalog> {
    return call("chat.Catalog");
  },
  /**
   * ContextUsage reads the bound live session's usage once (the card's open)
   * and returns it with the window the agent states. Read-only; a source
   * without usage yields the used count alone.
   */
  contextUsage(): Promise<ChatContextUsage> {
    return call("chat.ContextUsage");
  },
  /**
   * EditQueuedItem rewrites the text of one follow-up the worker has not
   * claimed yet (its place in the order stays) and returns the projection; a
   * claim race surfaces in the projection's Outcome instead of failing the call.
   */
  editQueuedItem(requestID: string, text: string): Promise<ChatBridgeState> {
    return call("chat.EditQueuedItem", requestID, text);
  },
  /**
   * InterruptAndSend is the explicit "cut in" path (the moshi barge-in analog):
   * one Escape stops the running turn, a short settle lets the TUI land on its
   * input box, then the prompt delivers via the canonical agent.prompt
   * transaction regardless of the now-stale working disposition. A ready
   * disposition skips the Escape (plain send); terminal-bound agents are
   * refused; a failed Escape aborts instead of typing into a running turn.
   */
  interruptAndSend(text: string): Promise<ChatBridgeState> {
    return call("chat.InterruptAndSend", text);
  },
  /**
   * LinkSession follows the suggested session's transcript, after the user's
   * click. The key must be one of the offered candidates; the projection after
   * the attempt is returned either way.
   */
  linkSession(key: string): Promise<ChatBridgeState> {
    return call("chat.LinkSession", key);
  },
  /**
   * ListFiles lists the chat pane's project directory entries matching the
   * composer's typed @ token (shallow; a "sub/dir/" prefix descends into the
   * subdirectory). Bounded, contains-match, dotfiles only when asked for.
   */
  listFiles(token: string): Promise<string[]> {
    return call("chat.ListFiles", token);
  },
  /**
   * Older pages the history-bound transcript one window up: the load runs on
   * the background lane and the refreshed projection arrives through the
   * chat:updated event; the returned state is the pre-load snapshot.
   */
  older(): Promise<ChatBridgeState> {
    return call("chat.Older");
  },
  /**
   * OpenMicrophoneSettings opens System Settings at Privacy → Microphone, the
   * one place a denied dictation can be re-enabled (the page cannot ask the
   * system again once it said no). The pane holds nothing: it is a local door.
   */
  openMicrophoneSettings(): Promise<void> {
    return call("chat.OpenMicrophoneSettings");
  },
  /**
   * OpenSubagent returns one sub-agent's own transcript for the drawer. The id
   * must be one the current chat listed; the page never names a path.
   */
  openSubagent(id: string): Promise<ChatBridgeSubagentView> {
    return call("chat.OpenSubagent", id);
  },
  /**
   * OpenTerminal switches the workspace surface to Terminal, for the page's
   * "Waiting for you in the terminal" card. Local surface switch only.
   */
  openTerminal(): Promise<void> {
    return call("chat.OpenTerminal");
  },
  /**
   * PickAttachment opens the native file picker and returns the chosen path,
   * empty when the user canceled. The path goes into the draft as an @mention
   * the agent's own CLI understands — files are local, nothing is uploaded.
   */
  pickAttachment(): Promise<string> {
    return call("chat.PickAttachment");
  },
  /**
   * ReorderQueued moves one queued follow-up to index to (delivery order =
   * list order; entries the worker already claimed stay pinned to the head
   * run) and returns the projection.
   */
  reorderQueued(requestID: string, to: number): Promise<ChatBridgeState> {
    return call("chat.ReorderQueued", requestID, to);
  },
  /**
   * ReviewChanges opens Diff Review (the WorkspacePrimarySurface Diff state)
   * for the card's repository, selecting path when it names a changed file.
   * It only switches the local surface: no Git runner call, no Herdr method.
   */
  reviewChanges(path: string): Promise<void> {
    return call("chat.ReviewChanges", path);
  },
  /**
   * SaveAttachment stores a pasted or dropped file under the cache dir's ChatAttachments (kept
   * 14 days, 200 MB) and returns its absolute path for the `@path` mention.
   */
  saveAttachment(dataBase64: string, mime: string, name: string): Promise<string> {
    return call("chat.SaveAttachment", dataBase64, mime, name);
  },
  /**
   * Send routes the prompt through the same disposition decision as the
   * native composer: SentNow delivers via the canonical agent.prompt
   * transaction, MidTurn queues, terminal-needed agents are refused. The
   * returned projection carries the outcome line; the page keeps its draft
   * whenever one is set (uncertain deliveries never look like clean sends).
   */
  send(text: string): Promise<ChatBridgeState> {
    return call("chat.Send", text);
  },
  /**
   * ShowContextMenu pops up the chat's macOS context menu at the pointer. The
   * page calls it from its contextmenu handler (editable fields keep the
   * system's own editing menu). It returns once the menu closes.
   */
  showContextMenu(in_: ChatMenuInput): Promise<void> {
    return call("chat.ShowContextMenu", in_);
  },
  /** Snapshot returns the current chat projection. */
  snapshot(): Promise<ChatBridgeState> {
    return call("chat.Snapshot");
  },
  /**
   * Stop interrupts the agent's current turn with one Escape (the product
   * decision of 2026-10-11): agent.send_keys with the named key "esc", the
   * same verified named-key operation the terminal's Esc uses — an interrupt,
   * never a process kill. The RPC runs off the UI lane; the projection
   * refreshes after it settles.
   */
  stop(): Promise<ChatBridgeState> {
    return call("chat.Stop");
  },
  /**
   * SwitchModel sends the provider's own typed model command (pi `/model`, omp
   * `/switch`: both session-only) through the ordinary prompt path.
   */
  switchModel(id: string): Promise<ChatBridgeState> {
    return call("chat.SwitchModel", id);
  },
  /**
   * Transcribe sends a recorded clip to the configured source (see
   * transcribeClip) and returns the text. The API key never reaches the page and
   * is never logged.
   */
  transcribe(audioBase64: string, mime: string): Promise<string> {
    return call("chat.Transcribe", audioBase64, mime);
  },
} as const;

/**
 * FilesPreviewBridge is the bound service of the WebView Files preview.
 * Bound methods run on their own goroutines; every Shell-state read
 * marshals onto the window UI lane first. Strictly read-only: the page has
 * no mutation channel — file operations stay native.
 */
export const filesPreview = {
  /**
   * Current returns the tree's current selection metadata (empty when no
   * file is selected). The page calls it once on mount.
   */
  current(): Promise<FilesPreviewTarget> {
    return call("filesPreview.Current");
  },
  /**
   * Open reads one file for preview. The request must be a file the page
   * owns — the live selection, planned for the WebView tier — so a stale
   * page request after the user clicked elsewhere, or for a file the native
   * code view shows, is refused instead of answering with content the tree
   * no longer shows. The flavor routes the read: Markdown pulls through
   * ReadPreview (1 MiB cap, symlink-guarded); images become a data URL
   * (24 MiB cap). Text never crosses the bridge — the native code view owns
   * it — so an error here is a stale race, not a user-facing state.
   */
  open(path: string): Promise<FilesPreviewContent> {
    return call("filesPreview.Open", path);
  },
  /**
   * OpenExternal hands an http(s) link from the page to the system browser.
   * The scheme is the whole gate: file:, javascript:, data: and everything
   * else are refused — the read-only page gets no filesystem or protocol
   * surface beyond this one door.
   */
  openExternal(rawURL: string): Promise<void> {
    return call("filesPreview.OpenExternal", rawURL);
  },
  /**
   * ShowContextMenu pops up the Files preview's macOS context menu at the
   * pointer; it returns once the menu closes.
   */
  showContextMenu(in_: FilesMenuInput): Promise<void> {
    return call("filesPreview.ShowContextMenu", in_);
  },
} as const;

/** ProjectsBridge is the bound service of the Projects WebView page. */
export const projects = {
  /**
   * Act runs one of the plugin's verbs on a task; the confirm dialogs, pickers
   * and refusals are the native ones.
   */
  act(kind: string, id: string): Promise<void> {
    return call("projects.Act", kind, id);
  },
  /** AddTask adds the task the sheet describes. */
  addTask(in_: ComposeInput): Promise<void> {
    return call("projects.AddTask", in_);
  },
  /** Back leaves the page the way the title bar's Back does. */
  back(): Promise<void> {
    return call("projects.Back");
  },
  /** CloseCompose dismisses the New Task sheet. */
  closeCompose(): Promise<void> {
    return call("projects.CloseCompose");
  },
  /**
   * LoadTab reads what a tab needs once: "changes", "settings" (open task) or
   * "reports" (open Project).
   */
  loadTab(tab: string): Promise<void> {
    return call("projects.LoadTab", tab);
  },
  /**
   * Manage runs a Project-level verb: confirms first where the verb is
   * destructive or spends tokens.
   */
  manage(op: string, target: string): Promise<void> {
    return call("projects.Manage", op, target);
  },
  /** OpenCompose opens the New Task sheet for the page's Project. */
  openCompose(delegate: boolean): Promise<void> {
    return call("projects.OpenCompose", delegate);
  },
  /**
   * OpenInWorkspace goes to the Chat target's pane in the Workspace (Terminal
   * and the rest of the pane's tools).
   */
  openInWorkspace(): Promise<void> {
    return call("projects.OpenInWorkspace");
  },
  /** OpenProject opens a Project's home. */
  openProject(name: string): Promise<void> {
    return call("projects.OpenProject", name);
  },
  /** OpenProjectWorkspace opens the task's worktree as a Workspace project. */
  openProjectWorkspace(): Promise<void> {
    return call("projects.OpenProjectWorkspace");
  },
  /**
   * OpenReport opens a report link (served page in the browser, file in the
   * system's opener).
   */
  openReport(link: string): Promise<void> {
    return call("projects.OpenReport", link);
  },
  /** OpenTask opens a task of the board. */
  openTask(id: string): Promise<void> {
    return call("projects.OpenTask", id);
  },
  /** OpenWorkBoard opens the plugin's own board Tab. */
  openWorkBoard(): Promise<void> {
    return call("projects.OpenWorkBoard");
  },
  /**
   * PickFiles asks for files and adds them to the page's Project Library under
   * mode ("always", "reference" or "task"); it returns the ids added so a New
   * Task sheet can tick them.
   */
  pickFiles(mode: string): Promise<string[]> {
    return call("projects.PickFiles", mode);
  },
  /** Pin stars or unstars a task or a Project. */
  pin(target: string, pinned: boolean): Promise<void> {
    return call("projects.Pin", target, pinned);
  },
  /** RemoveLibraryItem deletes a library item. */
  removeLibraryItem(id: string): Promise<void> {
    return call("projects.RemoveLibraryItem", id);
  },
  /**
   * SaveDescription replaces the task's description through the plugin and
   * optionally tells the agent already at work.
   */
  saveDescription(id: string, text: string, tell: boolean): Promise<void> {
    return call("projects.SaveDescription", id, text, tell);
  },
  /** SendLibraryItem hands one library file to the open task's running agent. */
  sendLibraryItem(id: string): Promise<void> {
    return call("projects.SendLibraryItem", id);
  },
  /** SetLibraryMode changes how a library item reaches the agents. */
  setLibraryMode(id: string, mode: string): Promise<void> {
    return call("projects.SetLibraryMode", id, mode);
  },
  /** Snapshot is the page's first read (later changes arrive as events). */
  snapshot(): Promise<ProjectsView> {
    return call("projects.Snapshot");
  },
} as const;

// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  /**
   * chatUpdated pushes the projection after every chat state mutation. Events
   * emitted before the page is ready are delivered once it is, so the page
   * also starts from Snapshot and stays current through this event alone.
   */
  chatUpdated: event<ChatBridgeState>("chat:updated"),
  /** chatMenu is the page's own menu actions (the ones only the page can run). */
  chatMenu: event<string>("chat:menu"),
  /**
   * chatSubagentOpen asks the page to open one listed sub-agent in its drawer
   * (the native sidebar's and quick panel's nested rows have no page click of
   * their own). The Shell emits it only once the sub's conversation is the
   * bound one, so the id is always one the current chat lists.
   */
  chatSubagentOpen: event<string>("chat:subagent-open"),
  /**
   * filesPreviewSelected fires whenever the tree selection changes. Events
   * emitted before the page is ready are replayed by the runtime, so the
   * page also starts from Current and stays current through this event alone.
   */
  filesPreview: event<FilesPreviewTarget>("files:preview"),
  /** filesMenu carries the one action only the page can run (selectAll). */
  filesMenu: event<string>("files:menu"),
  /**
   * projectsViewEvent carries every changed snapshot to the page. Events
   * emitted before the page is ready are replayed by the runtime.
   */
  projectsView: event<ProjectsView>("projects:view"),
} as const;
